  alpha: number,
  beta: number,
  observations: number,
  avgReturn: number,
  tags: string[],
): void {
  const now = new Date().toISOString();
  const posterior = alpha / (alpha + beta);
  this.db.prepare(`
    INSERT INTO beliefs (id, domain, subject, alpha, beta, posterior, observations, avg_return, tags, updated_at, created_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(id) DO UPDATE SET
