        content: `OWNER MANUAL ENTRY: ${ticker} ${side} | qty=${qty} | price=$${price.toFixed(2)} | Source: Alpaca fill reconciliation | ${ts}`,
        tags: ['trade', 'entry', 'owner_manual', ticker.toLowerCase(), side],
