    if (total >= 4 && winRate < minWinRate4) {
      return { should: false, reason: `${ticker}: ${history.wins}W/${history.losses}L (${(winRate*100).toFixed(0)}%) — reject (below ${(minWinRate4*100).toFixed(0)}% with ${total} trades${isBuffett ? ' Buffett' : ''})` };
