        ? 'mixed_manual_engine'
        : 'alpaca_reconcile';
    const closeReason = closeSource === 'owner_manual'
      ? (exitDirection === 'short' ? 'owner_manual_cover' : 'owner_manual_exit')
      : closeSource === 'mixed_manual_engine'
        ? 'mixed_manual_engine_exit'
        : 'alpaca_reconcile';
