      recordClosedTrade(store, {
        ticker: fill.ticker,
        direction: exitDirection,
        reason: closeReason,
        qty: fill.qty,
        entryPrice: avgEntry,
        exitPrice: fill.price,
        pnl: realizedPnl,
        openedAt: earliestBuyTime ?? '',
        closedAt: fill.time,
        orderId: fill.orderId,
        source: closeSource,
      });
