  ticker: string;
  entryPrice: number;
  exitPrice: number;
  shares: number;
  returnPct: number;
  pnl: number;
  holdTimeMs: number;
  exitReason: 'stop_loss' | 'take_profit' | 'trailing_stop' | 'signal' | 'circuit_breaker' | 'daily_goal_bank';
  closedAt: string;
